package com.sodi.metareports.user.dto; import jakarta.validation.constraints.*; import java.util.*;
public class UserForm { @NotBlank @Size(min=3,max=80) private String username; @NotBlank @Email private String email; @NotBlank @Size(max=100) private String firstName; @NotBlank @Size(max=100) private String lastName; @Size(min=12,max=100) private String password; @NotEmpty private Set<String> roleCodes=new HashSet<>();
 public String getUsername(){return username;} public void setUsername(String v){username=v;} public String getEmail(){return email;} public void setEmail(String v){email=v;} public String getFirstName(){return firstName;} public void setFirstName(String v){firstName=v;} public String getLastName(){return lastName;} public void setLastName(String v){lastName=v;} public String getPassword(){return password;} public void setPassword(String v){password=v;} public Set<String> getRoleCodes(){return roleCodes;} public void setRoleCodes(Set<String> v){roleCodes=v;}}
